#!/usr/bin/env bash
# Installs scripts/diagnose-bridge.ts - isolates the bridgeWithFee revert reason.
# After install, run (fill real values from a failed attempt):
#   cd nexum-contracts
#   NEXUM_VAULT_ADDRESS=0x7F3aCD7Ee5b01B06fb720D51FEBC3112121e61ED \
#   BRIDGE_AMOUNT=1000000 DEST_DOMAIN=<dest cctp domain> \
#   npx hardhat run scripts/diagnose-bridge.ts --network arc_testnet
# Use the wallet you actually bridged from (its key in nexum-contracts/.env).
set -euo pipefail
find_root() { local d="$PWD"; while [ "$d" != "/" ]; do [ -d "$d/nexum-contracts/scripts" ] && { echo "$d"; return; }; d="$(dirname "$d")"; done; [ -d "$HOME/AfriFX/Nexum-main/nexum-contracts/scripts" ] && { echo "$HOME/AfriFX/Nexum-main"; return; }; [ -d "$HOME/AfriFX/nexum-contracts/scripts" ] && { echo "$HOME/AfriFX"; return; }; return 1; }
ROOT="$(find_root)" || { echo "repo root not found"; exit 1; }
P="$ROOT/nexum-contracts/scripts/diagnose-bridge.ts"
if [ "${1:-}" = "--revert" ]; then rm -f "$P" && echo "removed $P"; exit 0; fi
tmp="$(mktemp)"; printf '%s' "" | base64 -d > "$tmp"
[ "$(sha256sum "$tmp" | cut -d' ' -f1)" = "9ea19285ef9dcf25498d53998b62975308c3a8dc91414648748a7ae505074d17" ] || { echo "checksum mismatch"; rm -f "$tmp"; exit 1; }
mv -f "$tmp" "$P"; echo "wrote $P"
echo "Now run it per the header comment (needs NEXUM_VAULT_ADDRESS + DEST_DOMAIN)."
